KG42.register("clusters-a73f72223e6f51216d4b6b71",{"id":"12-p2p_microgrid_trading::v142-d-K007","paper":"12-p2p_microgrid_trading","label":"Assumption of ignoring Elecbay service fees in the bidding simulation","record":{"cluster_id":"v142-d-K007","label":"Assumption of ignoring Elecbay service fees in the bidding simulation","market_meaning":"Ignores Elecbay service fees within the scope of the paper's non-cooperative bidding simulation, delimiting the scope of fee treatment included in that simulation.","mechanism_ids":["v141-a-M03"],"market_types":["LEM"],"process_stages":["settlement"],"scope_disposition":"conditional","scope_explanation":"Limited to the fee simplification in the M03 simulation and does not cover the M02 platform's arrangements for deducting service fees. The two scopes of applicability are retained separately; ignoring fees is not rewritten as a real-world platform fee rate that is always zero.","assembly_status":"assembled","boundary_rationale":"This assumption has distinct model applicability conditions and a distinct fee-treatment outcome; no existing payoff or bill calculation chain establishes a stronger dependency, so it is not forcibly merged with participation or counterparty preference merely because they share a source.","chain_bindings":[{"chain_id":"v141-c-R018","ownership":"primary","role":"core","rationale":"Independently retains the service fee simplification in the simulation and its applicability boundaries."}],"connections":[],"object_mappings":[],"gaps":[{"gap_id":"v142-d-K007-G001","category":"unverified_source","description":"The source status of the fee simplification remains unverified, and an independent audit of the original text has not yet been completed.","chain_ids":["v141-c-R018"],"object_refs":["v141-c-R018::phi::v141-c-R018-C001"],"evidence_ids":["v141-b-g01-ev-30"],"proposal_ids":[],"required_work":"Manually check the simulation scope within which service fees are ignored, and retain the distinction from the M02 platform's charging arrangements when subsequently connecting payoff or settlement models."}]},"rule_refs":["12-p2p_microgrid_trading::v141-c-R018"],"unresolved_rule_refs":[],"node_ids":["COMP-4d2d2e3f62af926d"]});
